draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // gut
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2, H/2 + 20);
  ctx.lineWidth = 3;
  ctx.stroke();

  // mood food
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Mood', W/2 - 75 + 30 * Math.sin(t), H/2 - 50);
  ctx.fillText('Food', W/2 + 45 + 30 * Math.sin(t), H/2 - 50);

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 20, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 170);
  ctx.lineTo(W/2, H/2 + 200);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 190);
  ctx.lineTo(W/2 - 30, H/2 + 220);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 190);
  ctx.lineTo(W/2 + 30, H/2 + 220);
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();
}
